{
  "positionId": "P06",
  "interviews": [
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "잠재 거래처와 접점을 만들어 첫 미팅으로 연결할 수 있는지 검증한다. 담당자에게 접근할 방식을 첫 미팅 성사 가능성과 연결해 선택하는 기준에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 신규 거래처 담당자에게 첫 미팅을 제안하는 상황이다.",
          "task": "첫 미팅을 제안할 접촉 방식을 선택해야 한다.",
          "action": "담당자와 연락이 닿을 가능성, 제품 소개에 관심을 보일 가능성 등을 접촉 방식의 선택 기준으로 설명한다.",
          "result": "선택 기준이 담당자와 접점을 만들고 첫 미팅으로 연결할 가능성을 높이는 데 어떻게 맞닿는지 설명한다."
        },
        "expectedEvidence": [
          "첫 미팅을 제안할 접촉 방식의 선택 기준",
          "그 기준과 담당자의 접촉 가능성 또는 제품 소개에 대한 관심 사이의 연결"
        ]
      },
      "question": "입사 후 신규 거래처 담당자에게 첫 미팅을 제안한다면, 담당자에게 처음 연락할 방식을 선택하는 기준은 무엇인가요?",
      "answerTip": "답변의 요점부터 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "담당자의 연락 가능 시간이나 선호 채널처럼 접촉 방식 선택에 적용할 수 있는 구체적인 기준을 제시한다.",
            "제시한 기준이 단순한 연락 편의를 넘어 제품 소개나 제안 기회가 되는 첫 미팅으로 이어질 가능성과 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "담당자에게 연락할 방식을 고르는 기준을 제시하지만 고객 특성이나 실제 접촉 상황에 적용하기에는 일반적이다.",
            "담당자와 접점을 만드는 데 관련된 기준이지만 첫 미팅으로 이어질 가능성과의 연결은 막연하다."
          ]
        },
        "poor": {
          "criteria": [
            "접촉 방식의 선택 기준을 제시하지 않고 전화나 방문 같은 방식만 나열한다.",
            "선택 기준이 본인의 편의에만 머물거나 담당자와의 접점 및 첫 미팅 성사와 무관하다."
          ]
        }
      }
    },
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기존 거래처의 발주 감소를 이탈 신호로 보고 거래 유지에 필요한 대응을 선택할 수 있는지 검증한다. 발주가 줄어든 거래처에 가장 먼저 취할 행동에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 기존 거래처의 발주가 줄어드는 상황이다.",
          "task": "거래를 이어갈 대응으로 가장 먼저 취할 행동을 선택해야 한다.",
          "action": "발주 감소와 관련된 거래처의 불편이나 달라진 수요를 직접 짚는 등 거래 유지에 맞는 첫 대응을 구체적으로 설명한다.",
          "result": "선택한 첫 대응으로 거래 중단 위험을 줄이거나 거래를 이어갈 실마리를 얻을 것으로 예상한다."
        },
        "expectedEvidence": [
          "거래를 이어가려고 가장 먼저 선택한 대응 행동",
          "그 행동에 포함된 접촉 대상이나 다룰 내용 등 실행 수준의 구체성"
        ]
      },
      "question": "입사 후 기존 거래처의 발주가 줄어든다면, 거래를 이어갈 대응으로 가장 먼저 선택할 행동은 무엇인가요?",
      "answerTip": "답변의 요점부터 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "발주 감소에 먼저 대응하는 행동 하나를 선택하고 접촉 대상이나 다룰 내용이 드러나도록 구체적으로 답한다.",
            "선택한 행동이 거래처의 불만이나 달라진 수요를 직접 다루는 등 거래를 이어가는 데 적합하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "거래처에 연락하거나 방문하는 등 첫 대응을 선택하지만 실제로 무엇을 다룰지는 막연하다.",
            "선택한 행동이 거래 유지와 관련은 있으나 발주 감소 상황을 겨냥한 대응으로는 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "가장 먼저 취할 행동을 선택하지 않고 고객 관리의 중요성 같은 일반론만 말한다.",
            "선택한 행동이 발주 감소에 대한 대응과 무관하거나 기존 거래처 대신 신규 거래처 발굴로 답을 돌린다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P12",
  "interviews": [
    {
      "categoryId": "P12-C1",
      "itemId": "P12-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "고객의 요구와 현장 조건을 장비 사양으로 구체화할 수 있는지 확인한다. 견적에 포함할 사양과 옵션을 정하는 기준에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 고객사가 현장에 맞는 원심 펌프의 견적을 요청한 상황이다.",
          "task": "고객의 요구와 현장 조건을 반영해 견적에 넣을 사양과 옵션을 정할 기준이 필요하다.",
          "action": "필요한 유량과 양정, 설치 공간과 사용 환경 등 고객의 조건을 사양과 옵션 선택에 연결하는 기준을 설명한다.",
          "result": "제시한 기준을 적용하면 고객에게 필요한 사양과 불필요한 옵션을 구분하고, 견적 협의의 범위를 구체화할 수 있음을 설명한다."
        },
        "expectedEvidence": [
          "견적에 넣을 사양과 옵션을 정하는 구체적인 기준",
          "고객의 요구나 현장 조건이 사양·옵션 선택에 연결되는 관계"
        ]
      },
      "question": "입사 후 고객사가 현장에 맞는 원심 펌프의 견적을 요청한다면, 견적에 넣을 사양과 옵션을 정하는 기준은 무엇인가요?",
      "answerTip": "말할 내용을 짧게 정리한 뒤 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "필요한 유량과 양정 등 고객의 사용 요구를 펌프 사양 선택과 연결해 구체적인 기준을 제시한다.",
            "설치 공간이나 사용 환경에 따라 필요한 사양과 옵션을 구분하는 기준이 견적 협의에 활용할 수 있을 만큼 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "고객의 요구나 현장 조건을 반영한다는 기준을 제시하지만 사양 선택과의 연결은 일반적이다.",
            "사양과 옵션을 정하는 기준에 답하지만 어떤 조건에서 선택이 달라지는지는 일부만 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "사양과 옵션을 정하는 기준 없이 고객에게 물어보겠다는 말이나 제품 소개에 머문다.",
            "고객의 요구와 현장 조건을 고려하지 않고 가격이나 판매 편의만으로 사양과 옵션을 정한다."
          ]
        }
      }
    },
    {
      "categoryId": "P12-C1",
      "itemId": "P12-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "장비의 기술 내용을 비전공 고객이 이해할 수 있는 말로 풀어낼 수 있는지 확인한다. 원심 펌프의 성능 곡선을 설명할 방식을 고르는 기준에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 비전공 고객이 원심 펌프의 성능 곡선을 쉽게 설명해 달라고 요청한 상황이다.",
          "task": "기술적 의미를 유지하면서 고객이 이해할 수 있는 설명 방식을 고를 기준이 필요하다.",
          "action": "고객에게 익숙한 표현으로 유량과 양정의 관계를 전달하고, 성능 곡선이 나타내는 조건과 한계를 왜곡하지 않는 설명 방식을 고르는 기준을 설명한다.",
          "result": "제시한 기준을 적용하면 고객이 성능 곡선을 단순한 수치 나열이 아니라 펌프의 동작 특성과 사용 조건을 나타내는 정보로 이해할 수 있음을 설명한다."
        },
        "expectedEvidence": [
          "비전공 고객에게 쓸 설명 방식을 고르는 구체적인 기준",
          "고객이 이해하기 쉬운 표현과 성능 곡선의 기술적 의미를 연결하는 판단 근거"
        ]
      },
      "question": "입사 후 비전공 고객이 원심 펌프의 성능 곡선을 쉽게 설명해 달라고 한다면, 고객에게 쓸 설명 방식을 고르는 기준은 무엇인가요?",
      "answerTip": "한 문장으로 요약한 뒤 풀어서 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "고객에게 익숙한 말로 유량과 양정의 관계를 전달할 수 있는지를 설명 방식의 구체적인 선택 기준으로 제시한다.",
            "쉽게 설명하더라도 동작 원리와 성능의 조건·한계를 왜곡하지 않아야 한다는 기준이 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "전문 용어를 줄이거나 쉬운 예를 사용한다는 선택 기준을 제시하지만 성능 곡선에 적용하는 내용은 일반적이다.",
            "고객의 이해 수준이나 기술적 정확성을 기준으로 언급하지만 설명 방식을 구분할 근거는 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "설명 방식을 고르는 기준에 답하지 않고 성능 곡선의 정의나 매뉴얼 내용만 나열한다.",
            "고객의 이해 여부나 기술적 의미와 관계없이 전문 용어를 그대로 읽거나 무조건 단순하게 말하는 것을 기준으로 삼는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 투약을 멈추고 확인할 수 있는지 평가한다. 평소와 다른 진통제 용량을 보고 담당의 확인이 필요하다고 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 근무 2년 차에 수술 후 환자의 진통제 용량이 평소의 두 배로 처방된 일이 있었다.",
          "task": "지원자는 해당 처방의 투약을 멈추고 담당의에게 확인했다.",
          "action": "처방에서 발견한 용량 차이가 투약을 보류하고 담당의에게 확인할 근거가 된 이유를 설명한다.",
          "result": "담당의 확인 결과 입력 오류였다는 사실을 자신의 판단 근거와 연결해 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의 확인이 필요하다고 판단한 근거",
          "판단의 근거가 된 평소 용량과 처방 용량의 차이",
          "담당의 확인으로 밝혀진 입력 오류와 판단 근거의 연결"
        ]
      },
      "question": "푸른결종합병원 정형외과 병동에서 수술 후 환자의 진통제 용량이 평소의 두 배로 처방됐을 때, 투약을 멈추고 담당의에게 확인한 근거는 무엇이었나요?",
      "answerTip": "본인이 했던 일을 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량이 평소의 두 배였다는 구체적인 차이를 투약 보류의 근거로 제시한다.",
            "용량 차이만으로 처방의 적절함을 확신할 수 없어 담당의 확인이 필요했다는 판단을 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 평소와 달라 투약을 멈추고 확인했다고 답하지만 구체적인 차이의 설명이 부족하다.",
            "환자 안전이나 오류 가능성을 근거로 제시하지만 해당 처방을 그대로 수행할 수 없다고 판단한 설명은 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈추고 담당의에게 확인한 근거를 제시하지 못하거나 당시 행동만 반복한다.",
            "처방을 의심한 용량 차이와 관계없는 업무 일반론으로 답하거나 확인 없이 투약해도 된다는 설명을 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보를 다음 근무자에게 빠짐없이 전달할 수 있는지 평가한다. 진통제 투여 시각을 인수인계에 포함할 정보로 선택한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "낙상 고위험 환자 인수인계 체크리스트 개선 활동에서 사고 보고서를 통해 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 확인했다.",
          "task": "지원자는 인수인계 체크리스트에 진통제 투여 시각과 보행 보조 여부를 넣자고 제안했다.",
          "action": "진통제 투여 시각을 다음 근무자에게 전달할 항목으로 선택한 근거를 설명한다.",
          "result": "진통제 투여 시각이 다음 근무자의 환자 상태 파악에 어떤 의미가 있는지 선택 근거와 연결해 설명한다."
        },
        "expectedEvidence": [
          "진통제 투여 시각을 인수인계 항목으로 선택한 근거",
